import{z as P,x as T,o as E,c as n,q as r,j as o,D as e,d as s,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"REST 与 gRPC","description":"","frontmatter":{"title":"REST 与 gRPC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rest-grpc.md","filePath":"cs/rest-grpc.md","lastUpdated":1791063341000}'),p={name:"cs/rest-grpc.md"};function R(A,a,d,C,B,c){const t=T("Mermaid");return E(),n("div",null,[a[2]||(a[2]=r('<h1 id="rest-与-grpc" tabindex="-1">REST 与 gRPC <a class="header-anchor" href="#rest-与-grpc" aria-label="Permalink to &quot;REST 与 gRPC&quot;">​</a></h1><div class="epigraph"><p>REST 用资源 URI 与 HTTP 方法约束接口；gRPC 用 HTTP/2 流跑 Protobuf RPC。都是应用合同，不是新的运输层。</p><footer>—— 据 Fielding 博士论文 REST；gRPC 超 HTTP/2 实践；RFC 9110 整理</footer></div><p><a href="/cs/http-semantics">HTTP 语义</a> 给方法。<a href="/cs/sse-server-push">上一课</a> 是一种推。缺口是<strong>两种常见 API 风格</strong>：REST 资源 vs gRPC 过程调用。本课不把 Protobuf 编码写完，下一课写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浏览器与公开 API 适合 REST：GET 可缓存、幂等合同清晰。微服务内部适合 gRPC：存根、流式 RPC、强类型。gRPC 默认 H2，浏览器要 grpc-web。REST 不是「用了 JSON 就 REST」：要统一接口与超媒体约束，课上钉常见子集。错误：REST 用状态码，gRPC 用 status 与 trailer。</p><p>不要把 gRPC 写成 QUIC 专属；H3 上的 gRPC 在演进。</p><p><span class="marginnote">Fielding 2000。gRPC 文档。本课对照，不教框架安装。</span></p><h3 id="合同不是运输" tabindex="-1">合同不是运输 <a class="header-anchor" href="#合同不是运输" aria-label="Permalink to &quot;合同不是运输&quot;">​</a></h3><p>REST 面向资源与缓存；gRPC 面向 RPC 与流。浏览器与公开 API 偏好前者。LB 要不要终止 H2 因此分叉。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：资源/方法 vs 服务/方法；缓存；浏览器；流。画：客户端 → HTTP → 资源；客户端 → H2 流 → RPC。与 WS：全双工消息 vs RPC 流。</p>',11)),(E(),o(l,null,{default:e(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REST%5B%22%E8%B5%84%E6%BA%90%20%2B%20HTTP%20%E6%96%B9%E6%B3%95%22%5D%20--%3E%20CACHE%5B%22%E5%8F%AF%E7%BC%93%E5%AD%98%20GET%22%5D%0A%20%20GRPC%5B%22Protobuf%20RPC%22%5D%20--%3E%20H2%5B%22HTTP%2F2%20%E6%B5%81%22%5D%0A%20%20GRPC%20--%3E%20TYP%5B%22%E5%BC%BA%E7%B1%BB%E5%9E%8B%E5%AD%98%E6%A0%B9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>负载均衡：REST 可 L7 看路径；gRPC 看服务与方法，要 H2 感知 LB。Cookie 少用于 gRPC，多用 token 头。超时与重试：REST 靠幂等头，gRPC 有 deadline，后课幂等会收。内容协商在 REST 常见，gRPC 固定编码。</p><p><span class="marginnote">术语翻译：REST 的「统一接口」就是把系统里的一切说成名词（资源）加几个标准动词（GET/PUT/POST/DELETE）；gRPC 则是把接口写成一句句过程调用（<code>OrderService.Pay</code>）。前者像自动售货机的固定按钮，后者像打电话给柜员点单——按钮人人会用，柜员能办复杂业务但要先拿「菜单」（.proto 文件）对齐。</span></p><p><span class="marginnote">常见误区：初学者容易以为「用了 JSON 和 HTTP 就是 REST」。Fielding 的 REST 要求统一接口、无状态、超媒体等约束；<code>POST /getUserById</code> 这种把动词写进路径的 RPC 风格接口，即使走 HTTP+JSON，也不是 REST——判断标准是资源建模与方法语义，不是报文格式。</span></p><p>与端到端：两种都要应用层校验，HTTP 成功不等于业务成功。</p>',5)),(E(),o(l,null,{default:e(()=>[i(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%90%8C%E4%B8%80%E6%AC%A1%E8%B0%83%E7%94%A8%22%5D%20--%3E%20Q%7B%22%E6%8E%A5%E5%8F%A3%E6%9A%B4%E9%9C%B2%E7%BB%99%E8%B0%81%3F%22%7D%0A%20%20Q%20--%20%22%E6%B5%8F%E8%A7%88%E5%99%A8%2F%E7%AC%AC%E4%B8%89%E6%96%B9%2FCDN%22%20--%3E%20R%5B%22REST%3A%20GET%20%E5%8F%AF%E7%BC%93%E5%AD%98%2C%20%E7%8A%B6%E6%80%81%E7%A0%81%E6%8A%A5%E9%94%99%22%5D%0A%20%20Q%20--%20%22%E5%86%85%E9%83%A8%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%AB%98%E9%A2%91%E8%B0%83%E7%94%A8%22%20--%3E%20G%5B%22gRPC%3A%20%E5%BC%BA%E7%B1%BB%E5%9E%8B%E5%AD%98%E6%A0%B9%20%2B%20deadline%22%5D%0A%20%20R%20--%3E%20L1%5B%22%E6%99%AE%E9%80%9A%20HTTP%20%E8%B4%9F%E8%BD%BD%E5%9D%87%E8%A1%A1%E5%8D%B3%E5%8F%AF%22%5D%0A%20%20G%20--%3E%20L2%5B%22%E9%9C%80%20H2%20%E6%84%9F%E7%9F%A5%20LB%2C%20%E6%B5%8F%E8%A7%88%E5%99%A8%E8%A6%81%20grpc-web%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>这张图回答的问题是「同一个业务调用，选型时先问什么」：分叉点是「接口暴露给谁」。面向浏览器与公网时，缓存与通用性优先，REST 几乎是默认；内部服务之间高频互调时，存根类型安全、流式与截止时间才值回引入成本。</p><p><span class="marginnote">数字实例：同一笔订单查询，JSON 文本报文约 500 字节，同样的字段用 Protobuf 编码常压到 100-200 字节；内部每秒百万次调用时，带宽与反序列化 CPU 的差距乘上一百万——这就是微服务内部偏爱 gRPC 最直接的账，而公开 API 损失的可缓存性与浏览器兼容往往比这点开销贵。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 GraphQL 的全部。序列化 JSON/Protobuf 是下一课。后课默认：REST 面向资源与缓存；gRPC 面向 RPC 与流。</p><p>公开互联网 API 强推 gRPC 会挡浏览器与缓存。</p><p>下一课<a href="/cs/serialization-protobuf">序列化：JSON / Protobuf</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>REST：资源、方法、缓存合同。</li><li>gRPC：H2 上的 RPC 与流。</li><li>LB、浏览器、缓存需求不同。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Fielding REST；gRPC over HTTP/2。</li></ul>',8))])}const h=P(p,[["render",R]]);export{S as __pageData,h as default};
